<?php
require_once __DIR__ . '/../../includes/auth.php';
requireLogin();
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); if (!$id) { http_response_code(404); exit('Receipt not found.'); }
$pdo = getDbConnection();
$stmt = $pdo->prepare("SELECT p.*, b.invoice_number, c.account_number, c.full_name, COALESCE(b.service_name_snapshot,s.service_name, legacy_s.service_name) AS service_name FROM payments p JOIN billing b ON b.id = p.billing_id JOIN customers c ON c.id = b.customer_id LEFT JOIN customer_services cs ON cs.id = b.customer_service_id LEFT JOIN services s ON s.id = cs.service_id LEFT JOIN services legacy_s ON legacy_s.id = c.service_id WHERE p.id = ? AND p.verification_status = 'verified'"); $stmt->execute([$id]); $payment = $stmt->fetch(); if (!$payment) { http_response_code(404); exit('Receipt not found.'); }
$pageTitle = 'Receipt ' . $payment['receipt_number']; include __DIR__ . '/../../includes/header.php'; include __DIR__ . '/../../includes/sidebar.php';
?>
<div class="d-flex justify-content-between align-items-center mb-3 no-print"><div><h3 class="mb-0">Payment Receipt</h3><small class="text-muted">Review and print the receipt for a verified payment.</small></div><div class="d-flex gap-2 action-buttons"><a href="index.php" class="btn btn-outline-secondary">Back</a><button class="btn btn-primary" onclick="window.print()"><i class="bi bi-printer"></i> Print / Save PDF</button></div></div>
<article class="card" id="invoice"><div class="card-body p-md-5"><div class="d-flex justify-content-between border-bottom pb-4 mb-4"><div><h2 class="mb-1">Cloud Interweb</h2><p class="mb-0 text-muted">Payment Receipt</p></div><div class="text-end"><h4 class="mb-1">RECEIPT</h4><div><?= htmlspecialchars($payment['receipt_number']) ?></div></div></div><div class="row mb-4"><div class="col-md-6"><h6>Received From</h6><strong><?= htmlspecialchars($payment['full_name']) ?></strong><br><?= htmlspecialchars($payment['account_number']) ?></div><div class="col-md-6 text-md-end mt-3 mt-md-0"><div><strong>Payment Date:</strong> <?= date('M j, Y', strtotime($payment['payment_date'])) ?></div><div><strong>Invoice:</strong> <?= htmlspecialchars($payment['invoice_number']) ?></div></div></div><table class="table"><tbody><tr><th>Service</th><td class="text-end"><?= htmlspecialchars($payment['service_name']) ?></td></tr><tr><th>Payment Method</th><td class="text-end"><?= htmlspecialchars($payment['payment_method']) ?></td></tr><tr><th>Reference Number</th><td class="text-end"><?= htmlspecialchars($payment['reference_number'] ?: ($payment['payment_method'] === 'Cash' ? 'Not applicable (cash)' : '-')) ?></td></tr></tbody><tfoot><tr><th class="text-end">Amount Received</th><th class="text-end">PHP <?= number_format((float) $payment['amount_paid'], 2) ?></th></tr></tfoot></table></div></article>
